#include "stdlib/stats/base/ndarray/sztest.h"
#include "stdlib/stats/base/ztest/one-sample/results/float32.h"
#include "stdlib/stats/base/ztest/alternatives.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>

#define NAME "sztest"
#define ITERATIONS 100000
#define REPEATS 3
#define MIN 1
#define MAX 6

/**
* Prints the TAP version.
*/
static void print_version( void ) {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
static void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total ); // TAP plan
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Prints benchmarks results.
*
* @param iterations  number of iterations
* @param elapsed     elapsed time in seconds
*/
static void print_results( int iterations, double elapsed ) {
	double rate = (double)iterations / elapsed;
	printf( "  ---\n" );
	printf( "  iterations: %d\n", iterations );
	printf( "  elapsed: %0.9f\n", elapsed );
	printf( "  rate: %0.9f\n", rate );
	printf( "  ...\n" );
}

/**
* Returns a clock time.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Generates a random number on the interval [0, 1).
*
* @return random number
*/
static double rand_double( void ) {
	return (double)rand() / ( (double)RAND_MAX + 1.0 );
}

/**
* Runs a benchmark.
*
* @param iterations   number of iterations
* @param len          array length
* @return             elapsed time in seconds
*/
static double benchmark( int iterations, int len ) {
	const enum STDLIB_NDARRAY_INDEX_MODE imode = STDLIB_NDARRAY_INDEX_ERROR;
	int8_t submodes[] = { STDLIB_NDARRAY_INDEX_ERROR };
	const enum STDLIB_NDARRAY_ORDER order = STDLIB_NDARRAY_ROW_MAJOR;
	uint8_t ybuf[ sizeof( struct stdlib_stats_ztest_one_sample_float32_results ) ];
	const int8_t altbuf[] = { STDLIB_STATS_ZTEST_TWO_SIDED };
	const float alphabuf[] = { 0.05f };
	const float mubuf[] = { 0.0f };
	const float sigmabuf[] = { 1.0f };
	int64_t *zshape = NULL;
	int64_t zstrides[] = { 0 };
	int64_t xshape[ 1 ];
	int64_t xstrides[ 1 ];
	const struct ndarray *arrays[ 6 ];
	struct ndarray *x;
	struct ndarray *y;
	struct ndarray *alt;
	struct ndarray *alpha;
	struct ndarray *mu;
	struct ndarray *sigma;
	double elapsed;
	float *data;
	double t;
	int i;

	xshape[ 0 ] = len;
	xstrides[ 0 ] = STDLIB_NDARRAY_FLOAT32_BYTES_PER_ELEMENT;

	data = (float *) malloc( len * sizeof( float ) );
	for ( i = 0; i < len; i++ ) {
		data[ i ] = (float)( ( rand_double()*10.0 ) - 5.0 );
	}
	// cppcheck-suppress invalidPointerCast
	x = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)data, 1, xshape, xstrides, 0, order, imode, 1, submodes );
	arrays[ 0 ] = x;

	// cppcheck-suppress invalidPointerCast
	y = stdlib_ndarray_allocate( STDLIB_NDARRAY_UINT8, ybuf, 0, zshape, zstrides, 0, order, imode, 0, submodes );
	arrays[ 1 ] = y;

	// cppcheck-suppress invalidPointerCast
	alt = stdlib_ndarray_allocate( STDLIB_NDARRAY_INT8, (uint8_t *)altbuf, 0, zshape, zstrides, 0, order, imode, 0, submodes );
	arrays[ 2 ] = alt;

	// cppcheck-suppress invalidPointerCast
	alpha = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)alphabuf, 0, zshape, zstrides, 0, order, imode, 0, submodes );
	arrays[ 3 ] = alpha;

	// cppcheck-suppress invalidPointerCast
	mu = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)mubuf, 0, zshape, zstrides, 0, order, imode, 0, submodes );
	arrays[ 4 ] = mu;

	// cppcheck-suppress invalidPointerCast
	sigma = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)sigmabuf, 0, zshape, zstrides, 0, order, imode, 0, submodes );
	arrays[ 5 ] = sigma;

	t = tic();
	for ( i = 0; i < iterations; i++ ) {
		stdlib_stats_sztest( arrays );
	}
	elapsed = tic() - t;

	stdlib_ndarray_free( x );
	stdlib_ndarray_free( y );
	stdlib_ndarray_free( alt );
	stdlib_ndarray_free( alpha );
	stdlib_ndarray_free( mu );
	stdlib_ndarray_free( sigma );
	free( data );

	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int count;
	int iter;
	int len;
	int i;
	int j;

	// Use the current time to seed the random number generator:
	srand( time( NULL ) );

	print_version();
	count = 0;
	for ( i = MIN; i <= MAX; i++ ) {
		len = pow( 10, i );
		iter = ITERATIONS / pow( 10, i-1 );
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			printf( "# c::%s:len=%d\n", NAME, len );
			elapsed = benchmark( iter, len );
			print_results( iter, elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
	}
	print_summary( count, count );
}
